function _validateOrder(bytes memory order) private view {
    (
        address makerToken,
        address takerToken,
        address feeRecipient,
        uint256 makerAmount,
        uint256 takerAmount
    ) = _extractOrderInfo(order);

    // No fee recipient allowed
    require(feeRecipient == address(0), "no fee recipient allowed");

    // MakerToken should never be WETH
    require(makerToken != address(WETH), "maker token must not be WETH");

    // TakerToken (proceeds) should always be WETH
    require(takerToken == address(WETH), "taker token must be WETH");

    address priceOracle = priceOracles[makerToken];

    // Price oracle not defined
    require(priceOracle != address(0), "price oracle not defined");

    uint256 slippageLimit = slippageLimits[makerToken];

    // Slippage limit not defined
    require(slippageLimit != 0, "slippage limit not defined");

    uint256 oraclePrice = _toUint(
        AggregatorV2V3Interface(priceOracle).latestAnswer()
    );

    uint256 priceFloor = (oraclePrice * slippageLimit) /
        SLIPPAGE_LIMIT_PRECISION;

    uint256 makerDecimals = 10**ERC20(makerToken).decimals();

    // makerPrice = takerAmount / makerAmount
    uint256 makerPrice = (takerAmount * makerDecimals) / makerAmount;

    require(makerPrice >= priceFloor, "slippage is too high");
}

function _fillOrder(
    LibOrder.Order memory order,
    uint256 takerAssetFillAmount,
    bytes memory signature
)
    internal
    returns (LibFillResults.FillResults memory fillResults)
{
    // Fetch order info
    LibOrder.OrderInfo memory orderInfo = getOrderInfo(order);

    // Fetch taker address
    address takerAddress = _getCurrentContextAddress();

    // Assert that the order is fillable by taker
    _assertFillableOrder(
        order,
        orderInfo,
        takerAddress,
        signature
    );

    // Get amount of takerAsset to fill
    uint256 remainingTakerAssetAmount = order.takerAssetAmount.safeSub(orderInfo.orderTakerAssetFilledAmount);
    uint256 takerAssetFilledAmount = LibSafeMath.min256(takerAssetFillAmount, remainingTakerAssetAmount);

    // Compute proportional fill amounts
    fillResults = LibFillResults.calculateFillResults(
        order,
        takerAssetFilledAmount,
        protocolFeeMultiplier,
        tx.gasprice
    );

    bytes32 orderHash = orderInfo.orderHash;

    // Update exchange internal state
    _updateFilledState(
        order,
        takerAddress,
        orderHash,
        orderInfo.orderTakerAssetFilledAmount,
        fillResults
    );

    // Settle order
    _settleOrder(
        orderHash,
        order,
        takerAddress,
        fillResults
    );

    return fillResults;
}

function calculateFillResults(
    LibOrder.Order memory order,
    uint256 takerAssetFilledAmount,
    uint256 protocolFeeMultiplier,
    uint256 gasPrice
)
    internal
    pure
    returns (FillResults memory fillResults)
{
    // Compute proportional transfer amounts
    fillResults.takerAssetFilledAmount = takerAssetFilledAmount;
    fillResults.makerAssetFilledAmount = LibMath.safeGetPartialAmountFloor(
        takerAssetFilledAmount,
        order.takerAssetAmount,
        order.makerAssetAmount
    );
    fillResults.makerFeePaid = LibMath.safeGetPartialAmountFloor(
        takerAssetFilledAmount,
        order.takerAssetAmount,
        order.makerFee
    );
    fillResults.takerFeePaid = LibMath.safeGetPartialAmountFloor(
        takerAssetFilledAmount,
        order.takerAssetAmount,
        order.takerFee
    );

    // Compute the protocol fee that should be paid for a single fill.
    fillResults.protocolFeePaid = gasPrice.safeMul(protocolFeeMultiplier);

    return fillResults;
}
